pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // Assume newOwner is not zero address to avoid edge case
        vm.assume(newOwner != address(0));

        // Transfer ownership to newOwner
        vm.prank(c.owner());
        c.transferOwnership(newOwner);

        // Record the owner after transfer
        address ownerAfterTransfer = c.owner();

        // Call owned()
        vm.prank(ownerAfterTransfer);
        c.owned();

        // The owner should remain unchanged after calling owned()
        assertTrue(c.owner() == ownerAfterTransfer);
    }
}

