pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _newOwner) public {
        // Assume _newOwner is not address(0) to ensure meaningful changes
        vm.assume(_newOwner != address(0));

        // Perform a transferOwnership call before owned()
        // First, we need to be the owner to call transferOwnership
        // Initially, owner is address(0) since it's uninitialized
        // So we directly call owned() to set the owner first? No, owned() does nothing.
        // Actually, we need to set the initial owner to something we control so we can call transferOwnership
        // Simpler: use vm.prank to impersonate the current owner, which is address(0) initially
        vm.prank(address(0));
        c.transferOwnership(_newOwner);

        // Now call owned()
        c.owned();

        // The owner should be _newOwner, not address(0)
        assertTrue(c.owner() == _newOwner);
    }
}

