pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        // Record owner before call
        address ownerBefore = c.owner();

        // Try to call owned() as caller
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("owned()"));

        // Record owner after call
        address ownerAfter = c.owner();

        // Rule: If the call succeeded, msg.sender was the owner before (and after) 
        // If it reverted, the owner is unchanged
        bool rule = (!success && ownerAfter == ownerBefore) || (success && caller == ownerBefore);
        assertTrue(rule);
    }
}

