pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0)); // avoid zero address issues
        address ownerBefore = c.owner();
        // Attempt to call owned() as the given caller
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("owned()"));
        // If the call reverted, we cannot observe owner change; skip those cases
        if (!success) return;
        address ownerAfter = c.owner();
        assertTrue(ownerAfter == ownerBefore, "Owner should not change after owned() call");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        // Record initial owner
        address initialOwner = c.owner();
        // Attempt to call owned() as any caller
        vm.prank(caller);
        c.owned();
        // After owned(), the only way to change owner is through transferOwnership by current owner
        // So we assert that the owner can only be changed by the initial owner (or current owner)
        // The rule: if the caller is not the initial owner, they cannot become the new owner
        // But we can test this more directly: after owned() by any caller, the owner is unchanged
        // because the onlyOwner modifier is the only way to update owner, and owned() doesn't update it
        assertTrue(c.owner() == initialOwner);
    }
}
